#include <vector>
#include <string>
#include <unordered_set>

class Solution {
public:
    int prefixConnectedGroups(std::vector<std::string>& words, int k) {
        std::unordered_set<std::string> groups;
        for (const auto& w : words) {
            groups.insert(w.substr(0, std::min<int>(k, w.length())));
        }
        return groups.size();
    }
};

import java.util.*;

class Solution {
    public int prefixConnectedGroups(String[] words, int k) {
        Set<String> groups = new HashSet<>();
        for (String w : words) {
            groups.add(w.substring(0, Math.min(k, w.length())));
        }
        return groups.size();
    }
}

